/**
 * 客户端翻译包 — 仅静态内联 zh（2026-10 首屏分包改造）
 *
 * @module core/i18n/client-bundles
 * @description 历史版本在此静态 import 全部 6 种语言（~867KB），被打进每个路由
 *              的首屏 JS chunk（架构评审 P0-1：实测 877KB）。SSR/首屏一律渲染
 *              zh（layout 的静态默认值），因此客户端初始资源只需 zh；
 *              其余语言经 loader.ts 的动态 import 在语言检测/切换时按需加载，
 *              由 LocaleContext 注入 addResourceBundle。
 *              原「AUTO-GENERATED by scripts/generate-i18n-bundles.ts」的生成脚本
 *              已不在仓库中（Vite 迁移遗留），本文件改为手工维护；语言键一致性
 *              由 scripts/gates/check-i18n.ts 在 lint/CI 强制，不依赖本文件。
 */

import zhAuth from "./locales/zh/auth.json";
import zhCommon from "./locales/zh/common.json";
import zhCrm from "./locales/zh/crm.json";
import zhErrors from "./locales/zh/errors.json";
import zhLearning from "./locales/zh/learning.json";
import zhMembership from "./locales/zh/membership.json";
import zhPayment from "./locales/zh/payment.json";
import zhProcurement from "./locales/zh/procurement.json";
import zhServices from "./locales/zh/services.json";
import zhSupplier from "./locales/zh/supplier.json";
import zhTraining from "./locales/zh/training.json";

const merge = (...modules: Record<string, unknown>[]): Record<string, string> => {
  const result: Record<string, string> = {};
  for (const m of modules) {
    if (typeof m === "object" && m !== null && "default" in m) {
      Object.assign(result, (m as { default: Record<string, string> }).default);
    } else {
      Object.assign(result, m);
    }
  }
  return result;
};

/** i18next 初始 resources：仅 zh（fallbackLng 同值，任何时刻都有完整中文兜底） */
export const INITIAL_RESOURCES: Record<string, { translation: Record<string, string> }> = {
  zh: { translation: merge(zhAuth, zhCommon, zhCrm, zhErrors, zhLearning, zhMembership, zhPayment, zhProcurement, zhServices, zhSupplier, zhTraining) },
};
